import type { HeaderFold } from './useHeaderFold.js';

/**
 * Where the reader was in the notebook when they left it for a word.
 *
 * Tester feedback, 2026-10-08: scroll past a dozen words, open one, press
 * Back, and the list was at its top again, so every word looked up cost a
 * scroll back down. On a phone a word is its own screen, so the list
 * unmounts; the browser's own scroll restoration cannot help either,
 * because the rows come from IndexedDB a few frames after the page is back
 * and the page is too short to scroll at the moment it tries.
 *
 * The filter, order and Show switches already outlive the screen
 * (viewMemory.ts). What this keeps is the rest of the reader's place: the
 * search, how many pages were turned, the day tab, which covered rows were
 * revealed, how far down the list was and how much of the header showed.
 *
 * It is kept in memory only, one place per notebook (or one for every
 * notebook at once), and never in the address: it is where somebody was a
 * moment ago, not something to share or to come back to after a restart.
 *
 * A place belongs to one history entry (`entry`, the router's location
 * key) and comes back only when that entry is returned to by Back or
 * Forward — the browser's arrows, Android's back key and an iPhone's
 * swipe all arrive as one — or when a screen sends the reader back to the
 * notebook and says so (`RETURN_TO_PLACE`). Tapping the Notebook tab is a
 * fresh visit and starts at the top, as it always has.
 */
export interface NotebookPlace {
  /** The history entry the notebook was showing. */
  entry: string;
  query: string;
  /** How many rows were on the page (the turned pages). */
  limit: number;
  /** The day tab, in the Pages order. */
  activePage: string | undefined;
  /** Rows revealed while the meanings were hidden. */
  revealed: readonly string[];
  /** How far down the window was. Used when the anchor row has gone. */
  scrollY: number;
  /** The first row on screen and how far from the top of the window it sat. */
  anchor: { wordId: string; top: number } | undefined;
  /** How much of the header was showing. */
  fold: HeaderFold;
}

/**
 * Router state a screen passes when it sends the reader to the notebook
 * rather than back to it (a word removed from its own screen), meaning
 * "put them where they were".
 */
export const RETURN_TO_PLACE = { notebookPlace: true } as const;

/** Whether a location's state carries `RETURN_TO_PLACE`. */
export function returnsToPlace(state: unknown): boolean {
  return (
    typeof state === 'object' && state !== null && 'notebookPlace' in state && state.notebookPlace === true
  );
}

/** The key a place is kept under: the notebook's id, or one for all of them. */
export function placeKey(notebookId: string | undefined, across: boolean): string | undefined {
  if (across) return '*';
  return notebookId;
}

const places = new Map<string, NotebookPlace & { key: string }>();

/** Keeps the place for the notebook it was taken in. */
export function rememberPlace(key: string, place: NotebookPlace): void {
  // Deleted first so the newest place is always the last one in the map.
  places.delete(key);
  places.set(key, { ...place, key });
}

/**
 * The place to put the reader back in, if this arrival is a return: the
 * entry they left (by Back or Forward), or the newest place there is when a
 * screen asked for it. Which notebook it belongs to comes with it, so a
 * place is never laid over a different notebook's list.
 */
export function placeToRestore(
  entry: string,
  popped: boolean,
  asked: boolean,
): (NotebookPlace & { key: string }) | undefined {
  const all = [...places.values()];
  if (popped) {
    const found = all.find((place) => place.entry === entry);
    if (found !== undefined) return found;
  }
  if (asked) return all.at(-1);
  return undefined;
}

/** For tests: forget every place. */
export function forgetPlaces(): void {
  places.clear();
}
